 3	public final class BalancedParentheses {
 4	    private static final String DEFAULT_SAMPLE = "[()()]{}";
 5	    private static final BracketProfile DEFAULT_BRACKETS = BracketProfile.standard();
 6	
 7	    private BalancedParentheses() {
 8	    }
 9	
10	    public static boolean isBalanced(CharSequence input) {
11	        return isBalanced(input, DEFAULT_BRACKETS);
12	    }
13	
14	    public static boolean isBalanced(CharSequence input, BracketProfile bracketProfile) {
15	        Objects.requireNonNull(input, "input");
16	        Objects.requireNonNull(bracketProfile, "bracketProfile");
17	        return new BalanceChecker(bracketProfile).check(input);
18	    }
19	
20	    public static void main(String[] args) {
21	        String sample = args.length > 0 ? args[0] : DEFAULT_SAMPLE;
22	        System.out.println(isBalanced(sample));
23	    }
24	
25	    private static final class BalanceChecker {
26	        private final BracketProfile bracketProfile;
27	        private char[] closingStack;
28	        private int depth;
29	
30	        private BalanceChecker(BracketProfile bracketProfile) {
31	            this.bracketProfile = bracketProfile;
32	        }
33	
34	        private boolean check(CharSequence input) {
35	            closingStack = new char[input.length()];
36	            depth = 0;
37	            for (int i = 0, length = input.length(); i < length; i++) {
38	                if (!accept(input.charAt(i))) {
39	                    return false;
40	                }
41	            }
42	            return depth == 0;
43	        }
44	
45	        private boolean accept(char c) {
46	            BracketToken token = bracketProfile.tokenFor(c);
47	            if (token == null) {
48	                return true;
49	            }
50	
51	            if (token.isOpening()) {
52	                pushExpectedClosing(token.expectedClosing());
53	                return true;
54	            }
55	
56	            return matchesClosing(token.character());
57	        }
58	
59	        private void pushExpectedClosing(char closing) {
60	            closingStack[depth++] = closing;
61	        }
62	
63	        private boolean matchesClosing(char closing) {
64	            return depth > 0 && closingStack[--depth] == closing;
65	        }
66	    }
67	}

 1	import java.util.HashMap;
 2	import java.util.HashSet;
 3	import java.util.Map;
 4	import java.util.Objects;
 5	import java.util.Set;
