 7	public final class BracketProfile {
 8	    private static final BracketProfile STANDARD = of(Map.of('(', ')', '{', '}', '[', ']'));
 9	
10	    private final Map<Character, BracketToken> bracketTokens;
11	
12	    private BracketProfile(Map<Character, BracketToken> bracketTokens) {
13	        this.bracketTokens = bracketTokens;
14	    }
15	
16	    public static BracketProfile standard() {
17	        return STANDARD;
18	    }
19	
20	    public static BracketProfile of(Map<Character, Character> openingToClosing) {
21	        Objects.requireNonNull(openingToClosing, "openingToClosing");
22	        return new BracketProfile(buildBracketTokens(Map.copyOf(openingToClosing)));
23	    }
24	
25	    BracketToken tokenFor(char c) {
26	        return bracketTokens.get(Character.valueOf(c));
27	    }
28	
29	    private static Map<Character, BracketToken> buildBracketTokens(
30	        Map<Character, Character> openingToClosing
31	    ) {
32	        Map<Character, BracketToken> tokens = new HashMap<>();
33	        Set<Character> openingBrackets = new HashSet<>();
34	        Set<Character> closingBrackets = new HashSet<>();
35	        for (Map.Entry<Character, Character> entry : openingToClosing.entrySet()) {
36	            char opening = entry.getKey().charValue();
37	            char closing = entry.getValue().charValue();
38	
39	            if (!closingBrackets.add(closing)) {
40	                throw new IllegalArgumentException("closing brackets must be unique");
41	            }
42	            if (opening == closing
43	                || openingBrackets.contains(closing)
44	                || closingBrackets.contains(opening)) {
45	                throw new IllegalArgumentException("opening and closing brackets must be distinct");
46	            }
47	
48	            openingBrackets.add(opening);
49	            tokens.put(Character.valueOf(opening), BracketToken.opening(opening, closing));
50	            tokens.put(Character.valueOf(closing), BracketToken.closing(closing));
51	        }
52	        return Map.copyOf(tokens);
53	    }
54	}
